public class HomeController : Controller
{
    public ActionResult Index()       // GET /Home/Index
    {
        var model = _svc.GetData();
        return View(model);            // renders Views/Home/Index.cshtml
    }
}

[Authorize]                       // authorization filter runs first
public ActionResult Edit(int id)  // model binding fills id
{
    return View(_svc.Get(id));    // ActionResult -> view engine renders
}

public class AdminAreaRegistration : AreaRegistration
{
    public override string AreaName => "Admin";
    public override void RegisterArea(AreaRegistrationContext c)
        => c.MapRoute("Admin_default", "Admin/{controller}/{action}/{id}",
             new { action = "Index", id = UrlParameter.Optional });
}

public class ProductController : Controller
{
    public ActionResult Details(int id)
        => View(_svc.Get(id));   // delegate logic to a service
}

[HttpPost]
public ActionResult Save(Product p) // built from posted fields
{
    if (!ModelState.IsValid) return View(p);
    _svc.Save(p); return RedirectToAction("Index");
}

[Authorize]            // authorization filter
[OutputCache(Duration=60)]  // result/caching filter
public ActionResult Index() => View();

public class LogFilter : ActionFilterAttribute
{
    public override void OnActionExecuting(ActionExecutingContext c)
        => Log($"Calling {c.ActionDescriptor.ActionName}"); // before the action
}

[OverrideAuthorization]   // ignore global authorization here
[AllowAnonymous]
public ActionResult PublicPage() => View();

public class ErrorFilter : HandleErrorAttribute
{
    public override void OnException(ExceptionContext c)
    {
        Log(c.Exception);
        c.Result = new ViewResult { ViewName = "Error" };
        c.ExceptionHandled = true;   // stop it bubbling up
    }
}

public class User {
    [Required, EmailAddress] public string Email { get; set; }
    [Range(18, 99)]          public int Age { get; set; }
